import {buildModel,num,place,time,sessionNames,statuses,stats,pairs,seasonPairs,pairTimeline,pairKey,driverStats,eventSummary,displayDate,championshipSeries,chartSegments,defaultComparison,adjacentStandingGaps,sessionPodium,positionGain,defaultEventKind,dashboardStats} from './model.mjs';
import {STORAGE_KEY,emptyStore,assertStore,persistStore,getPrediction,predictionConflict,canEdit,deadline,predictionPool,savePrediction,removePrediction,scorePrediction,mergeImported} from './user.mjs';
import {simulateChampionship,standingTitle} from './championship.mjs';
import {flagFor,countryCode,layoutFor,mediaEntry} from './media.mjs';
let mediaPack=null;
const app=document.getElementById('app');
const esc=x=>String(x??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=x=>esc(num(x)), st=x=>esc(statuses[x]||x||'—');
const tabs=[['gps','Этапы'],['table','Таблица'],['stand','Зачёт'],['mates','Напарники'],['dash','Дашборд']];
let userStore,storageRaw=null,storageError='',notice='',predDraft=[];
let m,y,tab='gps',eventId=null,kind='race',round=null,mateRound=null,calendarFilter='all',mateMode='season',mateSelected=null,mateKind='race',statSort='points',dashMode='stats',compareIds=[],chartRound=null,chanceResult=null,chanceSimulations=10000;
function selectOptions(items,value){return items.map(([v,n])=>`<option value="${esc(v)}"${String(v)===String(value)?' selected':''}>${esc(n)}</option>`).join('');}
function tbl(headers,rows){return `<div class="tw v2-table"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function empty(msg){return `<div class="card mu">${esc(msg)}</div>`;}
const navIcons={gps:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18m-13 5h2m4 0h2"/>',table:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 9h18M3 14h18M9 4v16m6-16v16"/>',stand:'<path d="M8 21v-4h8v4M12 17v-5M7 3h10v5a5 5 0 0 1-10 0V3ZM7 5H3v2a4 4 0 0 0 4 4m10-6h4v2a4 4 0 0 1-4 4M5 21h14"/>',mates:'<circle cx="8" cy="7" r="3"/><circle cx="17" cy="8" r="3"/><path d="M2 20v-3a6 6 0 0 1 12 0v3m2-7a5 5 0 0 1 6 5v2"/>',dash:'<path d="M3 3v18h18M7 16v-5m5 5V6m5 10V9"/>'};
function navIcon(k){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${navIcons[k]}</svg>`;}
function flag(name){const src=flagFor(name,mediaPack),code=countryCode(name,mediaPack);return src?`<img class="media-flag" src="${esc(src)}" alt="" title="${esc(name)}" loading="lazy">`:code?`<small class="mu" title="${esc(name)}">${esc(code.toUpperCase())}</small>`:'';}
function visualStatus(item){return ({dated_source:'Датированный источник; точный сезон требует проверки',provisional_representative:'Предварительная эмблема команды; сезон не подтверждён',manufacturer_brand:'Знак производителя, не логотип гоночной команды',fan_icon:'Авторская иконка, не официальный логотип',historical_photo:'Историческое фото, не логотип'})[item?.periodStatus]||'Эмблема: историческая принадлежность требует проверки';}
function iconMedia(group,id,year,label){const item=mediaEntry(mediaPack,group,id,year);const initials=String(label||'').split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();return item?`<img class="media-icon ${group==='logos'?'media-logo':'media-photo'}" src="${esc(item.src)}" alt="" title="${esc(item.author+' · '+item.license+(group==='photos'?' · фото не обязательно этого сезона':' · '+visualStatus(item)))}" loading="lazy">`:`<span class="media-icon media-placeholder" aria-hidden="true">${esc(initials||'—')}</span>`;}
function driverLabel(id,year=y){const d=m.drivers.get(id),name=m.driver(id);return `<span class="media-label">${iconMedia('photos',id,year,name)}<span class="media-name">${flag(d?.nationality)}<span>${esc(name)}</span></span></span>`;}
function teamLabel(id,entry,year=y){const name=m.team(id,entry),item=mediaEntry(mediaPack,'logos',id,year),type=item?.periodStatus,mark=type==='historical_photo'?'фото':type==='fan_icon'?'иконка':type==='manufacturer_brand'?'бренд':'';return `<span class="media-label">${iconMedia('logos',id,year,name)}<span class="media-name">${flag(m.teams.get(id)?.nationality)}<span>${esc(name)}${mark?` <small class="mu" title="${esc(visualStatus(item))}">(${mark})</small>`:''}</span></span></span>`;}
function circuitArt(e,large=false){const item=mediaEntry(mediaPack,'circuits',layoutFor(e,mediaPack),e.season);const c=m.circuits.get(e.circuitId);return item?`<span class="circuit-art ${large?'large':''}"><img src="${esc(item.src)}" alt="Схема ${esc(c?.name)}" title="${esc(item.author+' · '+item.license)}" loading="lazy"></span>`:large?`<span class="circuit-art large circuit-missing"><span>Схема пока не загружена</span></span>`:'';}
function credits(){if(!mediaPack)return '';const items=new Map();for(const k of ['photos','logos','circuits'])for(const item of Object.values(mediaPack[k]||{})){if(item?.source?.startsWith('https://'))items.set(item.source,item);}return `<details class="card media-credits"><summary>Источники изображений (${items.size})</summary><p class="mu">Фото пилотов могут быть сняты в другой сезон. Командные изображения включают предварительные эмблемы, знаки производителей, авторские иконки и исторические фото. Это не означает подтверждение точного логотипа каждого сезона. Схемы — конфигурации из архива F1DB v2026.21.0.</p>${[...items.values()].map(i=>`<p><a href="${esc(i.source)}" target="_blank" rel="noopener noreferrer">${esc(i.file||i.source.split('/').at(-1))}</a> · ${esc(i.author)} · ${esc(i.license)}${i.licenseUrl?.startsWith('https://')?` · <a href="${esc(i.licenseUrl)}" target="_blank" rel="noopener noreferrer">лицензия</a>`:''}</p>`).join('')}</details>`;}
function eventButton(e){const z=eventSummary(m,e);const statusClass=m.completed(e)?'done':e.status==='scheduled'?'planned':'other';return `<button class="v2-event v2-event-rich ${e.status==='scheduled'?'v2-upcoming':''}" data-event="${esc(e.id)}"><span class="v2-event-round"><small>ЭТАП</small>${String(e.round).padStart(2,'0')}</span><span class="v2-event-main"><b>${flag(z.circuit?.country)} ${esc(e.name)}</b><small>${esc(z.circuit?.name||'—')} · ${esc(z.circuit?.country||'—')}</small><span class="event-meta"><small>${esc(displayDate(e.date))}</small><span class="event-status ${statusClass}">${st(e.status)}</span>${m.session(e,'sprint')?'<span class="sprint-label">Спринт</span>':''}</span></span><span class="v2-event-results">${z.winner?`<span><small>Победитель</small><b>${driverLabel(z.winner.driverId,e.season)}</b><small>${teamLabel(z.winner.constructorId,z.winner.entrantId,e.season)}</small></span>`:''}${z.pole?`<span><small>Поул (P1 квалификации)</small><b>${esc(m.driver(z.pole.driverId))}</b></span>`:''}${!z.winner&&!z.pole?'<small>Результаты отсутствуют</small>':''}</span><span class="event-art">${circuitArt(e)}</span><span aria-hidden="true" class="v2-chevron">›</span></button>`;}
function overview(es,done){const next=es.find(e=>e.status==='scheduled'||e.status==='in_progress'),last=es.filter(m.completed).at(-1),featured=next||last;const drivers=m.standing(y,'drivers'),teams=m.standing(y,'constructors');const leader=(s,k)=>{const r=s?.rows[0];return r?`<strong>${k==='drivers'?driverLabel(r.entityId):teamLabel(r.entityId,r.entrantId)}</strong><span class="leader-points">${fmt(r.points)} <small>очков</small></span>`:'<strong>Нет зачёта</strong>';};const pct=es.length?Math.round(done/es.length*100):0;return `<section class="season-overview" aria-label="Обзор сезона"><div class="season-hero"><div class="hero-copy"><span class="eyebrow">СЕЗОН ${y} / ${next?'В КАЛЕНДАРЕ ЕСТЬ НЕЗАВЕРШЁННЫЕ ЭТАПЫ':done===es.length?'ВСЕ ЭТАПЫ ЗАВЕРШЕНЫ':'ОБЗОР КАЛЕНДАРЯ'}</span><h2>${featured?flag(m.circuits.get(featured.circuitId)?.country):''} ${featured?esc(featured.name):'Календарь чемпионата'}</h2><p>${featured?`${next?'Предстоящий или текущий этап':'Последний завершённый этап'} · ${esc(displayDate(featured.date))} · ${esc(m.circuits.get(featured.circuitId)?.name||'—')}`:'Нет этапов'}</p>${featured?`<button class="pr" data-event="${esc(featured.id)}">${next?'Открыть этап':'Результаты этапа'} <span aria-hidden="true">↗</span></button>`:''}</div><div class="hero-track">${featured?circuitArt(featured):''}</div><div class="hero-decoration" aria-hidden="true"><i></i><i></i><i></i><b>${y}</b></div></div><div class="season-metrics"><div class="season-metric"><span class="eyebrow">ПРОГРЕСС СЕЗОНА</span><strong>${done}<small> / ${es.length}</small></strong><div class="season-progress" role="progressbar" aria-label="Завершённые этапы" aria-valuemin="0" aria-valuemax="${es.length||1}" aria-valuenow="${done}"><span style="width:${pct}%"></span></div><small>${pct}% этапов завершено</small></div><button class="season-metric" data-tab="stand"><span class="eyebrow">ЛИДЕР · ПИЛОТЫ</span>${leader(drivers,'drivers')}<small>Последний опубликованный зачёт ↗</small></button><button class="season-metric" data-tab="stand"><span class="eyebrow">ЛИДЕР · КОМАНДЫ</span>${leader(teams,'constructors')}<small>Последний опубликованный зачёт ↗</small></button></div></section>`;}
function calendar(){const es=m.eventsOf(y),done=es.filter(m.completed).length,filtered=es.filter(e=>calendarFilter==='all'||(calendarFilter==='completed'?m.completed(e):!m.completed(e)&&e.status!=='cancelled'));return overview(es,done)+`<div class="v2-section-head calendar-heading"><div><span class="eyebrow">РАСПИСАНИЕ И РЕЗУЛЬТАТЫ</span><h2 class="v2-heading">Календарь сезона ${y}</h2></div><span class="mu">${filtered.length} из ${es.length} этапов</span></div><div class="chips v2-section">${[['all','Все'],['completed','Завершённые'],['upcoming','Незавершённые']].map(([v,n])=>`<button data-filter="${v}" aria-pressed="${calendarFilter===v}" class="${calendarFilter===v?'pr':''}">${n}</button>`).join('')}</div><div class="calendar-list">${filtered.length?filtered.map(eventButton).join(''):empty('Нет этапов в этой категории.')}</div>`;}
function standings(){const es=m.eventsOf(y),rs=[...new Set([...m.snapshots(y,'drivers'),...m.snapshots(y,'constructors')].map(s=>s.afterRound))].sort((a,b)=>a-b);if(!rs.length)return empty('Опубликованных зачётов пока нет.');const r=round??rs.at(-1);const recentTeams=new Map();for(const e of es.filter(e=>e.round<=r))for(const rr of m.session(e,'race')?.results||[])recentTeams.set(rr.driverId,rr);const table=(k,title)=>{const s=m.standing(y,k,r);if(!s)return `<h2 class="v2-heading">${title}</h2>`+empty('Нет опубликованного снимка на этом этапе.');const champ=standingTitle(m,y,k,s),gaps=adjacentStandingGaps(s.rows);return `<section class="card standings-card"><h2 class="v2-heading">${title} · ${y}</h2><div class="standing-head standing-grid"><span>Место</span><span>${k==='drivers'?'Пилот':'Команда / заявка'}</span><span>Очки</span><span title="Разница до предыдущей позиции">Δ очков</span></div>${s.rows.map((x,i)=>{const isChamp=champ?.id===(x.entrantId||x.entityId),t=recentTeams.get(x.entityId),gap=gaps[i];return `<div class="standing-row standing-grid ${isChamp?'is-champion':''}"><span class="standing-position">${esc(place(x))}</span><span class="standing-identity">${k==='drivers'?driverLabel(x.entityId):teamLabel(x.entityId,x.entrantId)}${k==='drivers'&&t?`<small class="standing-team">${esc(m.team(t.constructorId,t.entrantId))}</small>`:''}${isChamp?`<small class="champion-mark"><svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M3 6l5 4 4-6 4 6 5-4-2 12H5zM5 21h14"/></svg>${champ.status==='final'?(k==='drivers'?'Чемпион':'Кубок конструкторов'):'Титул обеспечен'}</small>`:''}</span><b class="standing-points">${fmt(x.points)}<small class="standing-wins">Побед: ${fmt(x.wins)}</small></b><span class="standing-gap ${gap===0?'equal':''}">${gap==null?'—':gap>0?'+'+fmt(gap):fmt(gap)}</span></div>`;}).join('')}</section>`;};return `<div class="card v2-ctrl standings-control"><label for="round">Зачёт после этапа</label><select id="round">${selectOptions(rs.map(n=>[n,`${n}. ${es.find(e=>e.round===n)?.name||''}`]),r)}</select><p class="mu">Δ — очки относительно предыдущей строки зачёта, не лидера. Титул отмечается в последнем зачёте при завершённом сезоне или строгой математической недосягаемости по данным календаря.</p></div>`+table('drivers','Личный зачёт')+table('constructors','Кубок конструкторов');}
function matrix(){const es=m.eventsOf(y),s=m.standing(y,'drivers'),ids=[...new Set([...(s?.rows.map(r=>r.entityId)||[]),...m.driverIds(y)])];const total=new Map((s?.rows||[]).map(r=>[r.entityId,r.points]));if(!ids.length)return empty('Пока нет результатов пилотов.');return `<p class="mu">В ячейках — начисленные пилоту очки гонки и спринта; «—» означает отсутствие записи. Последняя строка — опубликованный зачёт, не сумма по современной шкале.</p><div class="tw"><table><thead><tr><th class="s1">Гран-при</th>${ids.map(id=>`<th class="th" style="--c:var(--ac)">${driverLabel(id)}</th>`).join('')}</tr></thead><tbody>${es.map(e=>`<tr><th class="s1"><button data-event="${esc(e.id)}">${e.round}. ${esc(e.name)}</button></th>${ids.map(id=>`<td>${fmt(m.points(e,id))}</td>`).join('')}</tr>`).join('')}</tbody><tfoot><tr><th class="s1">Очки в зачёте</th>${ids.map(id=>`<td>${fmt(total.get(id))}</td>`).join('')}</tr></tfoot></table></div>`;}
function gainLabel(r){const n=positionGain(r);return n==null?'—':`<span class="race-gain ${n>0?'gain-up':n<0?'gain-down':''}" aria-label="${n>0?'Выиграно':n<0?'Потеряно':'Без изменения'} ${Math.abs(n)} позиций">${n>0?'↑ +':n<0?'↓ −':''}${Math.abs(n)}</span>`;}
function eventHero(e){const c=m.circuits.get(e.circuitId),race=m.session(e,'race'),q=m.session(e,'qualifying');const ss=e.sessions.filter(s=>s.kind==='race'||s.kind==='sprint');const prev=m.eventsOf(e.season).filter(x=>x.round<e.round).at(-1),next=m.eventsOf(e.season).find(x=>x.round>e.round);return `<div class="gp-nav"><button data-back="1">‹ К сезону</button><div class="chips">${prev?`<button data-event="${esc(prev.id)}" aria-label="Предыдущий этап">‹ ${prev.round}</button>`:''}${next?`<button data-event="${esc(next.id)}" aria-label="Следующий этап">${next.round} ›</button>`:''}</div></div><section class="gp-hero card"><div class="gp-copy"><span class="eyebrow">СЕЗОН ${e.season} / ЭТАП ${String(e.round).padStart(2,'0')}</span><h2>${flag(c?.country)} ${esc(e.name)}</h2><p class="gp-location">${esc(c?.name||'Автодром не указан')} ${c?.country?' · '+esc(c.country):''}</p><div class="gp-meta"><span>${esc(displayDate(e.date))}</span><span class="event-status ${m.completed(e)?'done':e.status==='scheduled'?'planned':'other'}">${st(e.status)}</span>${ss.some(s=>s.kind==='sprint')?'<span class="sprint-label">Спринт-уикенд</span>':''}</div>${race?.status==='final'?'':race?`<p class="mu">${st(race.status)} · итоговый подиум появится после публикации результатов.</p>`:''}${race?`<button data-kind="prediction" class="${kind==='prediction'?'':'pr'}">${race.status==='final'?'Мой прогноз':'Открыть прогноз'} ↗</button>`:''}</div><div class="gp-track"><span class="eyebrow">КОНФИГУРАЦИЯ ТРАССЫ</span>${circuitArt(e,true)}<small class="mu">${esc(c?.locality||c?.country||'')}</small></div></section>`;}
function podiumView(e,s){const rows=sessionPodium(s);if(!rows.some(Boolean))return '';return `<section class="card gp-podium"><div class="gp-section-title"><div><span class="eyebrow">ОКОНЧАТЕЛЬНАЯ КЛАССИФИКАЦИЯ</span><h2 class="v2-heading">${s.kind==='sprint'?'Подиум спринта':'Подиум гонки'}</h2></div><span class="mu">Фото могут быть другого сезона</span></div><div class="gp-podium-grid">${[2,1,3].map(p=>{const r=rows[p-1];return `<article class="gp-place gp-p${p}" aria-label="Место ${p}"><div class="gp-person">${r?`${iconMedia('photos',r.driverId,e.season,m.driver(r.driverId))}<b>${flag(m.drivers.get(r.driverId)?.nationality)} ${esc(m.driver(r.driverId))}</b><div class="gp-team">${teamLabel(r.constructorId,r.entrantId,e.season)}</div><small class="mu">${fmt(r.points)} очков · Δ ${gainLabel(r)}</small>`:'<span class="gp-no-result">Нет подтверждённого результата</span>'}</div><div class="gp-step"><strong>${p}</strong><span>${p===1?'ПОБЕДИТЕЛЬ':'МЕСТО'}</span></div></article>`;}).join('')}</div></section>`;}
function sessionFacts(e,s){if(!s||s.status!=='final'||!['race','sprint'].includes(s.kind))return '';const winner=sessionPodium(s)[0],q=m.session(e,s.kind==='race'?'qualifying':'sprint_qualifying'),poles=q?.status==='final'?q.results.filter(r=>r.classified===true&&r.position===1):[],pole=poles.length===1?poles[0]:null,fl=m.data.fastestLaps.find(x=>x.sessionId===s.id);const facts=[['Победитель',winner?driverLabel(winner.driverId,e.season):'—',winner?time(winner.timeMs):'—'],['P1 квалификации',pole?driverLabel(pole.driverId,e.season):'—',pole?'Первая позиция классификации':'Нет итоговых данных'],['Быстрейший круг',fl?driverLabel(fl.driverId,e.season):'—',fl?`${time(fl.timeMs)} · круг ${fmt(fl.lap)}`:'Нет данных у источника']];return `<div class="gp-facts">${facts.map(([label,value,note])=>`<div class="card gp-fact"><span class="eyebrow">${label}</span><strong>${value}</strong><small class="mu">${esc(note)}</small></div>`).join('')}</div>`;}
function detail(e){const s=m.session(e,kind),fl=m.data.fastestLaps.find(x=>x.sessionId===s?.id);let body=eventHero(e)+`<div class="chips v2-section gp-sessions" aria-label="Сессии этапа">${e.sessions.map(x=>`<button data-kind="${esc(x.kind)}" aria-pressed="${kind===x.kind}" class="${kind===x.kind?'pr':''}">${esc(sessionNames[x.kind]||x.kind)}</button>`).join('')}${m.session(e,'race')?`<button data-kind="prediction" aria-pressed="${kind==='prediction'}" class="${kind==='prediction'?'pr':''}">Прогноз</button>`:''}</div>`;if(kind==='prediction')return body+predictionView(e);if(!s)return body+empty('Нет такой сессии.');body+=sessionFacts(e,s)+podiumView(e,s)+`<div class="gp-section-title gp-results-title"><div><span class="eyebrow">${st(s.status)} · ${s.results.length} записей</span><h2 class="v2-heading">${esc(sessionNames[kind]||kind)} · результаты</h2></div></div>`;if(!s.results.length)return body+empty('Результаты пока отсутствуют.');const q=kind.includes('qualifying'),raceLike=['race','sprint'].includes(kind);if(raceLike)body+='<p class="mu">Δ позиций = место на старте минус место в классификации. Для позиции старта 0, неизвестного старта и неклассифицированных результатов Δ не рассчитывается.</p>';body+=tbl(q?['Место','Пилот','Команда','Время / Q1–Q3','Статус']:['Место','Пилот','Команда','Старт',...(raceLike?['Δ позиций']:[]),'Круги','Время','Отставание','Очки','Статус'],s.results.map(r=>{const base=[esc(place(r)),driverLabel(r.driverId,e.season),teamLabel(r.constructorId,r.entrantId,e.season)];return q?[...base,esc(r.qualifyingTimesMs?.map(time).join(' / ')||time(r.timeMs)),st(r.status)+(r.position==null&&r.positionText?` <small title="Исходная позиция">(${esc(r.positionText)})</small>`:'')]:[...base,r.gridPosition===0?'0 / вне решётки':fmt(r.gridPosition),...(raceLike?[gainLabel(r)]:[]),fmt(r.laps),esc(time(r.timeMs)),esc(time(r.gapMs)),fmt(r.points),st(r.status)];}));if(fl&&!(raceLike&&s.status==='final'))body+=`<div class="card fl-card"><b>Быстрейший круг</b><p>${esc(m.driver(fl.driverId))} · ${esc(time(fl.timeMs))} · круг ${fmt(fl.lap)}</p></div>`;body+=`<details class="card v2-source"><summary>Источники</summary>${s.sourceIds.map(id=>{const z=m.sources.get(id);return `<p>${esc(z?.provider)} · ${esc(z?.revision||'')}<br>${esc(z?.url)}</p>`;}).join('')}</details>`;return body;}
function matesRound(){const es=m.eventsOf(y).filter(e=>m.session(e,'race')?.results.length);if(!es.length)return empty('Нет гоночных результатов для сравнения.');const e=es.find(e=>e.round===mateRound)||es.at(-1);return `<div class="card v2-ctrl"><label for="mate-round">Составы на этапе</label><select id="mate-round">${selectOptions(es.map(e=>[e.round,`${e.round}. ${e.name}`]),e.round)}</select><p class="mu">Составы по фактическим записям гонки, без переноса команд между сезонами.</p></div>`+pairs(m,e).map(rr=>`<div class="card"><h3 class="v2-heading">${teamLabel(rr[0].constructorId,rr[0].entrantId)}</h3>${rr.map(r=>`<div class="li"><b>${esc(place(r))}</b><span class="nm">${driverLabel(r.driverId)}<small class="mu"> · ${st(r.status)}</small></span><b>${fmt(r.points)}</b></div>`).join('')}</div>`).join('');}
