function mateScore(v,label){const n=v.a+v.b+v.tie;return `<div class="h2h-score"><div class="h2h-score-head"><span>${label}</span><small class="mu">${n?`${n} сравн.`:'Нет сопоставимых результатов'} · исключено ${v.skipped}</small></div><div class="h2h-numbers"><b class="h2h-a">${v.a}</b><span class="mu">${v.tie?`Равных: ${v.tie}`:':'}</span><b class="h2h-b">${v.b}</b></div><div class="h2h-bar" role="img" aria-label="${v.a} : ${v.b}, равных ${v.tie}">${n?`<span class="h2h-fill-a" style="flex:${v.a}"></span><span class="h2h-fill-tie" style="flex:${v.tie}"></span><span class="h2h-fill-b" style="flex:${v.b}"></span>`:''}</div></div>`;}
