function predictionView(e){const p=getPrediction(userStore,m,e),conflict=predictionConflict(userStore,m,e),editable=!storageError&&!conflict&&canEdit(m,e),s=m.session(e,'race'),score=scorePrediction(m,e,p);const t=deadline(e,s);const pool=predictionPool(m,e).sort((a,b)=>m.driver(a).localeCompare(m.driver(b)));const dateLabel=Number.isFinite(t)?new Date(t).toLocaleString('ru-RU'):'неизвестен';const rows=editable?predDraft:p?.driverIds||[];
 const head=`<div class="card"><h3 class="v2-heading">Мой прогноз финиша</h3><p class="mu">От 1 до 10 мест. Прогноз хранится только в этом браузере, не меняет официальный зачёт. ${s?.scheduledAt?'Срок по времени старта':'Точное время старта отсутствует: консервативный срок до дня гонки'}: ${esc(dateLabel)} (местное время).</p>${conflict?'<p role="alert">Привязка этапа отсутствует или изменилась. Прогноз сохранён в хранилище, редактирование заблокировано.</p>':''}${p?`<p class="mu">${userStore.bindings[p.sessionId].imported?'Восстановлено из копии; заявленная дата (своевременность не подтверждена)':'Сохранено'}: ${esc(new Date(p.updatedAt).toLocaleString('ru-RU'))}</p>`:''}${!editable?'<p>Редактирование закрыто.</p>':''}`;
 const picks=rows.length?`<ol class="pred-list">${rows.map((id,i)=>`<li><span>${driverLabel(id)}</span>${editable?`<span class="pred-actions"><button data-pred-up="${i}" aria-label="Выше" ${i===0?'disabled':''}>↑</button><button data-pred-down="${i}" aria-label="Ниже" ${i===rows.length-1?'disabled':''}>↓</button><button data-pred-remove="${i}" aria-label="Удалить пилота">×</button></span>`:''}</li>`).join('')}</ol>`:'<p class="mu">Нет выбранных пилотов.</p>';
 const available=pool.filter(id=>!rows.includes(id));const edit=editable?`<p class="mu">Список по данным сезона${m.driverIds(e.season).length?'':' (предыдущий доступный сезон)'}, не подтверждённая заявка на гонку.</p><div class="pred-add"><label for="pred-driver">Добавить пилота</label><select id="pred-driver" ${!available.length||rows.length>=10?'disabled':''}>${selectOptions(available.map(id=>[id,m.driver(id)]),available[0])}</select><button data-pred-add="1" ${!available.length||rows.length>=10?'disabled':''}>Добавить</button></div><div class="chips v2-section"><button class="pr" data-pred-save="1" ${!rows.length?'disabled':''}>Сохранить прогноз</button><button data-pred-reset="1">Отменить изменения</button>${p?'<button data-pred-delete="1">Удалить прогноз</button>':''}</div>`:'';
 const result=score?`<div class="card"><h3 class="v2-heading">${userStore.bindings[p.sessionId].imported?'Ретроспективная оценка (импорт)':'Точность прогноза'} · ${score.score} очков</h3><p>Точных мест: ${score.exact} · ±1: ${score.close} · Победитель: ${score.winner?'да':'нет'} · Подиум: ${score.podium}/3</p>${tbl(['Прогноз','Пилот','Фактическое место'],p.driverIds.map((id,i)=>[String(i+1),esc(m.driver(id)),esc(place(s.results.find(r=>r.driverId===id&&r.classified===true&&r.started===true)||{}))]))}</div>`:(p?'<p class="mu">Оценка появится после загрузки окончательных результатов гонки.</p>':'');return head+picks+edit+'</div>'+result;}
function predictionDash(){const all=userStore.user.predictions.filter(p=>userStore.bindings[p.sessionId].season===y),matched=m.eventsOf(y).map(e=>[e,getPrediction(userStore,m,e)]).filter(([,p])=>p);return `<div class="card"><h2 class="v2-heading">Мои прогнозы · ${y}</h2><p class="mu">Точные места +5, отклонение на одно место +2, победитель +10, каждый угаданный участник подиума +3. Только окончательные классифицированные результаты. Данные локальные, не защищены от ручной подмены часов или файлов. Импорт — восстановление архива, не подтверждение своевременности подачи.</p><div class="chips"><button data-user-export="1" ${storageError?'disabled':''}>Экспорт резервной копии</button><button data-user-import="1" ${storageError?'disabled':''}>Импорт прогнозов</button></div><p class="mu">${all.length-matched.length?`Непривязанных прогнозов: ${all.length-matched.length}. Сохранены в резервной копии.`:'Все сохранённые прогнозы сезона привязаны.'}</p></div>`+(matched.length?tbl(['Гран-при','Выбрано пилотов','Очки прогноза'],matched.map(([e,p])=>[`<button data-pred-event="${esc(e.id)}">${esc(e.name)}</button>`,String(p.driverIds.length),fmt(scorePrediction(m,e,p)?.score)+(userStore.bindings[p.sessionId].imported?' (импорт)':'')])):empty('Нет сохранённых прогнозов. Откройте будущий этап → Прогноз.'));}
function probability(value){return `${Number(value||0).toFixed(1).replace('.',',')}%`;}
function chanceRows(title,rows,championId,kind){
 const isDriver=kind==='drivers';
 const body=rows.map((r,i)=>[String(i+1),esc(r.name),fmt(r.points),fmt(r.expectedFinalPoints),fmt(r.maxFuturePoints),`<b class="chance-pct">${probability(r.probability)}</b>`,championId===r.id?'<span class="chance-lock">Титул обеспечен</span>':(isDriver&&!r.active?'Нет в последнем составе':'—')]);
 return `<h3 class="v2-heading v2-section">${title}</h3>`+tbl(['№','Пилот / команда','Сейчас','Ожидаемые итоговые','Максимум ещё','Шанс титула','Статус'],body);
}
function championshipChances(){
 const intro=`<section class="card chance-intro"><h2 class="v2-heading">Шансы на чемпионство · ${y}</h2><p class="mu">Модель оценивает личный зачёт и Кубок конструкторов отдельно. Используются последние опубликованные очки, текущий состав из последней завершённой гонки и форма сезона.</p><div class="chance-controls"><label>Количество сценариев<select id="chance-sims">${selectOptions([[2000,'2 000'],[5000,'5 000'],[10000,'10 000'],[20000,'20 000'],[50000,'50 000']],chanceSimulations)}</select></label><button class="pr" data-chance-run="1">${chanceResult?'Пересчитать':'Рассчитать шансы'}</button></div></section>`;
 if(!chanceResult)return intro+`<div class="card"><b>Как работает расчёт</b><p class="mu">Сначала проверяется математическая возможность догнать лидера. Если титул уже обеспечен, показывается точный результат без симуляции. Иначе проводится Монте-Карло с учётом вероятности схода и исторической формы пилотов.</p><p class="mu">Результаты являются модельной оценкой, а не официальным прогнозом FIA.</p></div>`;
 const r=chanceResult;
 if(r.status!=='ok')return intro+`<div class="card chance-warning"><b>${esc(r.message||'Расчёт недоступен.')}</b>${r.blockers?.length?`<ul>${r.blockers.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}</div>`;
 const mode=r.simulations===0?'Математическая проверка: титулы уже обеспечены':`Монте-Карло: ${r.simulations.toLocaleString('ru-RU')} сценариев`;
 const summary=`<div class="v2-grid chance-summary"><div class="card"><small>Осталось гонок</small><div class="v2-kpi">${r.remaining.races}</div></div><div class="card"><small>Осталось спринтов</small><div class="v2-kpi">${r.remaining.sprints}</div></div><div class="card"><small>Последний зачёт после этапа</small><div class="v2-kpi">${r.currentAfterRound}</div></div><div class="card"><small>Метод</small><b>${esc(mode)}</b></div></div>`;
 const rules=`<div class="card"><b>Регламент ${r.season}</b><p class="mu">Гонка: ${esc(r.scoring.description)}. Спринт: ${r.scoring.sprintPoints.length?r.scoring.sprintPoints.join('–'):'не проводятся'}. ${r.scoring.fastestLapBonus?'Дополнительное очко за быстрейший круг в топ-10.':'Бонуса за быстрейший круг нет.'}${r.scoring.doubleFinalRace?' Удвоенные очки на финальном этапе.':''}${r.scoring.sprintMinDistancePercent?` Для спринта требуется не менее ${r.scoring.sprintMinDistancePercent}% дистанции.`:''}${r.scoring.shortenedRacePoints?' Для сокращённой гонки действует отдельная шкала очков; симуляция использует полную дистанцию.':''}</p><small class="mu">Состав взят из ${esc(r.rosterSource)}.</small></div>`;
 const alerts=`<div class="card chance-notes"><b>Ограничения модели</b><ul>${r.warnings.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`;
 return intro+summary+rules+chanceRows('Личный зачёт',r.drivers,r.mathematicallyClinched.drivers,'drivers')+chanceRows('Кубок конструкторов',r.constructors,r.mathematicallyClinched.constructors,'constructors')+alerts;
}
function dash(){return `<div class="chips v2-section"><button data-dash-mode="stats" class="${dashMode==='stats'?'pr':''}">Статистика</button><button data-dash-mode="charts" class="${dashMode==='charts'?'pr':''}">Графики и сравнение</button><button data-dash-mode="predictions" class="${dashMode==='predictions'?'pr':''}">Мои прогнозы</button><button data-dash-mode="chances" class="${dashMode==='chances'?'pr':''}">Шансы на титул</button></div>`+(dashMode==='stats'?dashStats():dashMode==='charts'?compareDash():dashMode==='predictions'?predictionDash():championshipChances());}
function render(){const i=m.years.indexOf(y),title=eventId?'Гран-при':({gps:'Обзор сезона',table:'Таблица результатов',stand:'Чемпионат',mates:'Сравнение напарников',dash:'Аналитический дашборд'}[tab]);app.innerHTML=`<aside class="app-sidebar"><div class="brand"><span class="brand-mark" aria-hidden="true">F<span>1</span></span><span><b>F1 ANALYTICS</b><small>SEASON INTELLIGENCE</small></span></div><span class="sidebar-label">ЧЕМПИОНАТ</span><nav aria-label="Основная навигация">${tabs.map(([k,n])=>`<button data-tab="${k}" class="${tab===k?'on':''}" ${tab===k?'aria-current="page"':''}>${navIcon(k)}<span>${n}</span></button>`).join('')}</nav><div class="sidebar-foot"><span class="draft-dot"></span> ${m.data.datasetStatus==='verified'?'VERIFIED':'DRAFT'} · v2.0<br><small>Локальные прогнозы</small></div></aside><div class="workspace"><header><div class="page-title"><span class="eyebrow">F1 ANALYTICS / ${y}</span><h1>${title}</h1></div><div class="header-controls"><span class="ynav"><button data-year="${m.years[i-1]??''}" ${i===0?'disabled':''} aria-label="Предыдущий сезон">‹</button><select class="year-select" id="year" aria-label="Сезон">${selectOptions(m.years.map(x=>[x,x]),y)}</select><button data-year="${m.years[i+1]??''}" ${i===m.years.length-1?'disabled':''} aria-label="Следующий сезон">›</button></span><label class="theme-control"><span>Тема</span><select id="theme">${selectOptions([['auto','Авто'],['light','Светлая'],['dark','Тёмная']],userStore.user.preferences.theme)}</select></label></div></header><div class="preview-note"><b>${m.data.datasetStatus==='verified'?'VERIFIED · проверенная база':'DRAFT · предварительный просмотр'}</b> · Официальные данные только для чтения. Прогнозы локальные; автообновление публичного сайта пока отключено. Источник: <a href="https://github.com/f1db/f1db" target="_blank" rel="noopener noreferrer">F1DB</a> · <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a> · данные преобразованы F1 Analytics. ${m.data.datasetStatus==='verified'?'<a href="SOURCE.txt">Атрибуция релиза</a>.':'Флаги: <a href="https://github.com/googlefonts/noto-emoji" target="_blank" rel="noopener noreferrer">Noto Emoji</a>.'}</div>${storageError||notice?`<div class="preview-note" role="status">${esc(storageError||notice)}</div>`:''}<main>${eventId?detail(m.events.get(eventId)):({gps:calendar,table:matrix,stand:standings,mates,dash}[tab])()}${credits()}</main></div>`;}
function changeYear(v){if(!m.years.includes(v))return;y=v;eventId=null;round=null;mateRound=null;mateSelected=null;mateKind='race';calendarFilter='all';compareIds=[];chartRound=null;chanceResult=null;predDraft=[];notice='';setPreference('selectedSeason',y);render();}
app.addEventListener('click',ev=>{const b=ev.target.closest('button');if(!b||!m)return;const d=b.dataset;if(d.year)changeYear(Number(d.year));else if(d.tab){tab=d.tab;eventId=null;render();}else if(d.event&&m.events.has(d.event)){eventId=d.event;kind=defaultEventKind(m.events.get(eventId));render();}else if(d.kind&&eventId){if(d.kind==='prediction')openPrediction(m.events.get(eventId));else kind=d.kind;render();}else if(d.predEvent&&m.events.has(d.predEvent)){eventId=d.predEvent;openPrediction(m.events.get(eventId));render();}else if(d.userImport){const picker=document.createElement('input');picker.type='file';picker.accept='.json,application/json';picker.onchange=async()=>{try{const file=picker.files?.[0];if(!file)return;if(storageError)throw Error(storageError);if(file.size>5*1024*1024)throw Error('Файл превышает 5 МБ.');const incoming=JSON.parse(await file.text());const next=mergeImported(userStore,incoming,m);if(JSON.stringify(next)===JSON.stringify(userStore)){notice='Импорт: изменений нет.';render();return;}if(!confirm('Восстановить прогнозы без замены состава, порядка и даты существующих? Импорт не подтверждает своевременность. Новых: '+(next.user.predictions.length-userStore.user.predictions.length)+'.'))return;if(localStorage.getItem(STORAGE_KEY)!==storageRaw)throw Error('Хранилище изменилось.');const key=STORAGE_KEY+':backup:'+new Date().toISOString();if(localStorage.getItem(key)!==null)throw Error('Резервная копия уже существует.');localStorage.setItem(key,JSON.stringify(userStore));commitUser(next);notice='Импорт завершён. Резервная копия сохранена.';}catch(e){notice=e.message;}render();};picker.click();}else if(d.userExport){const blob=new Blob([JSON.stringify(userStore,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='f1-user-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}else if(eventId&&kind==='prediction'&&Object.keys(d).some(k=>k.startsWith('pred'))){const e=m.events.get(eventId);try{if(!canEdit(m,e)||predictionConflict(userStore,m,e)||storageError)throw Error('Редактирование закрыто.');if(d.predAdd){const id=document.getElementById('pred-driver')?.value;if(id&&predictionPool(m,e).includes(id)&&!predDraft.includes(id)&&predDraft.length<10)predDraft.push(id);}else if(d.predRemove!==undefined)predDraft.splice(Number(d.predRemove),1);else if(d.predUp!==undefined||d.predDown!==undefined){const i=Number(d.predUp??d.predDown),j=i+(d.predUp!==undefined?-1:1);if(i>=0&&i<predDraft.length&&j>=0&&j<predDraft.length)[predDraft[i],predDraft[j]]=[predDraft[j],predDraft[i]];}else if(d.predSave){commitUser(savePrediction(userStore,m,e,predDraft));notice='Прогноз сохранён.';render();return;}else if(d.predReset){predDraft=[...(getPrediction(userStore,m,e)?.driverIds||[])];}else if(d.predDelete){if(!confirm('Удалить сохранённый прогноз?'))return;commitUser(removePrediction(userStore,m,e));predDraft=[];}notice='';}catch(e){notice=e.message;}render();}else if(d.filter){calendarFilter=d.filter;render();}else if(d.matePair){mateSelected=d.matePair;render();document.querySelector(".h2h-control")?.scrollIntoView({block:"start"});}else if(d.mateKind){mateKind=d.mateKind;render();}else if(d.mateMode){mateMode=d.mateMode;render();}else if(d.dashMode){dashMode=d.dashMode;render();}else if(d.chanceRun){try{chanceResult=simulateChampionship(m,y,{simulations:chanceSimulations});notice='';}catch(e){notice=e.message;}render();}else if(d.back){eventId=null;render();}});
app.addEventListener('change',ev=>{if(!m)return;const v=Number(ev.target.value);if(ev.target.id==='theme'){setPreference('theme',ev.target.value);render();}else if(ev.target.id==='year')changeYear(v);else if(ev.target.id==='round'){round=v;render();}else if(ev.target.id==='mate-pair'){mateSelected=ev.target.value;render();}else if(ev.target.id==='mate-round'){mateRound=v;render();}else if(ev.target.id==='chart-round'){chartRound=v;render();}else if(/^compare-[01]$/.test(ev.target.id)){const j=Number(ev.target.id.at(-1));if(m.driverIds(y).includes(ev.target.value)&&!compareIds.includes(ev.target.value)){compareIds[j]=ev.target.value;render();}}else if(ev.target.id==='stat-sort'){statSort=ev.target.value;render();}else if(ev.target.id==='chance-sims'){chanceSimulations=Number(ev.target.value);}});
try{const r=await fetch('./official.json',{cache:'no-store'});if(!r.ok)throw Error('HTTP '+r.status);m=buildModel(await r.json());document.title=m.data.datasetStatus==='verified'?'F1 Analytics 2.0':'F1 Analytics 2.0 — DRAFT';try{const mr=await fetch('./visual-media.json',{cache:'no-store'});if(!mr.ok)throw Error('HTTP '+mr.status);const mp=await mr.json();if(mp.version!==1||!mp.photos||!mp.logos||!mp.circuits)throw Error('Некорректный медиапакет');mediaPack=mp;}catch(e){notice='Медиапакет недоступен. Используются обозначения без изображений.';}loadUser();y=m.years.includes(userStore.user.preferences.selectedSeason)?userStore.user.preferences.selectedSeason:m.years.at(-1);applyTheme();render();}catch(e){app.innerHTML=`<main><div class="card"><h2>Не удалось загрузить базу</h2><p>${esc(e.message)}</p><p>Проверьте доступность official.json и адрес приложения. Для локального запуска используйте HTTP-сервер из инструкции, не file://.</p></div></main>`;}
